        function MMDDYYYY(str) {
            var ndateArr = str.toString().split(' ');
            var Months = 'Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec';
            return (parseInt(Months.indexOf(ndateArr[1]) / 4) + 1) + '-' + ndateArr[2] + '-' + ndateArr[3];
